window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[239]={"id":"239","numero":239,"titre":"Acrosyndromes","objectifs":[{"id":"239-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un phénomène de Raynaud, d’une acrocyanose, d’une érythermalgie, d’une ischémie digitale et d’une engelure","contenu":"<p>Un <span class=\"kw-def\"><strong>acrosyndrome</strong></span> est un <span class=\"kw-def\">trouble vasospastique ou obstructif</span> qui touche principalement le <span class=\"kw-def\">réseau microvasculaire des extrémités</span> — <span class=\"kw-clinique\">les</span> mains le plus souvent, parfois les pieds, le nez ou les oreilles. Cinq entités sont à connaître, réparties en acrosyndromes <strong>vasomoteurs</strong> (anomalie réversible du tonus vasculaire) et acrosyndromes <strong>trophiques</strong> (atteinte tissulaire constituée).</p>\n\n      <table >\n        <thead>\n          <tr><th>Acrosyndrome</th><th>Mécanisme</th><th><span class=\"kw-clinique\">Évolution</span></th><th>Caractère dominant</th><th>Gravité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Phénomène de Raynaud</span></td>\n            <td><span class=\"kw-clinique\">Vasoconstriction paroxystique</span> au froid</td>\n            <td>Crises en <span class=\"kw-chiffre\">3 phases</span></td>\n            <td><span class=\"kw-def\">Vasomoteur</span></td>\n            <td>Bénin si primitif ; <span class=\"kw-alerte\">variable</span> si secondaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Acrocyanose</span></td>\n            <td><span class=\"kw-clinique\">Microangiopathie fonctionnelle</span> bénigne</td>\n            <td><span class=\"kw-clinique\">Permanente</span></td>\n            <td><span class=\"kw-def\">Vasomoteur</span></td>\n            <td>Bénin — touche <span class=\"kw-chiffre\">10 %</span> de la population</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Érythermalgie</span></td>\n            <td><span class=\"kw-clinique\">Vasodilatation paroxystique</span></td>\n            <td><span class=\"kw-clinique\">Paroxystique</span> (crises)</td>\n            <td><span class=\"kw-def\">Vasomoteur</span></td>\n            <td><span class=\"kw-alerte\">À explorer</span> — rechercher un <span class=\"kw-etio\">syndrome myéloprolifératif</span> sous-jacent</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Engelure</span></td>\n            <td>Composante <strong>trophique</strong> après <span class=\"kw-clinique\">froid humide</span></td>\n            <td>Subaiguë, régressive en <span class=\"kw-chiffre\">2-3 semaines</span></td>\n            <td><span class=\"kw-def\">Trophique</span></td>\n            <td>Bénin ; distinguer la <span class=\"kw-alerte\">pseudo-engelure</span> (<span class=\"kw-def\">lupus</span>-engelures)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Ischémie digitale permanente</span></td>\n            <td><span class=\"kw-clinique\">Lésions artérielles ou microcirculatoires</span></td>\n            <td><span class=\"kw-clinique\">Permanente</span></td>\n            <td><span class=\"kw-def\">Trophique</span></td>\n            <td><span class=\"kw-alerte\"><strong>Urgence 🔥</strong></span> — risque de <span class=\"kw-clinique\">nécrose</span> digitale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir — vasomoteur <span class=\"kw-bio\">vs</span> trophique.</strong> <span class=\"kw-clinique\">Les</span> acrosyndromes <strong>vasomoteurs</strong> (<span class=\"kw-clinique\">phénomène de Raynaud</span>, érythermalgie, acrocyanose) traduisent une anomalie réversible du tonus vasculaire. Les acrosyndromes <strong>trophiques</strong> (engelure, ischémie digitale permanente, <span class=\"kw-clinique\">syndrome de l</span>'orteil bleu — rang C) comportent une atteinte tissulaire qui peut laisser des séquelles.\n      </div>","frequence":0},{"id":"239-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques des principaux acrosyndromes","contenu":"<p>Le diagnostic des acrosyndromes est avant tout <span class=\"kw-clinique\">clinique</span> : il repose sur l'<span class=\"kw-clinique\">interrogatoire</span> et l'examen, complétés au besoin par des <span class=\"kw-clinique\">photographies prises par le patient</span> pendant la crise. Connaître la sémiologie propre à chaque entité permet de <span class=\"kw-clinique\">les</span> distinguer dès la première lecture.</p>\n\n      <table >\n        <thead>\n          <tr><th>Acrosyndrome</th><th><span class=\"kw-def\">Terrain</span></th><th>Présentation clinique</th><th><span class=\"kw-clinique\">Évolution</span> / Durée</th><th>Signes négatifs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Phénomène de Raynaud</span></td>\n            <td><span class=\"kw-clinique\">Femme jeune</span> surtout ; concerne <span class=\"kw-chiffre\">5 %</span> de la population (jusqu'à <span class=\"kw-chiffre\">15 %</span> des femmes en France)</td>\n            <td><strong>Déclenchement :</strong> froid, variations de température, humidité, émotion ; <br><strong>Topographie :</strong> une ou plusieurs phalanges, doigts variables d'une crise à l'autre, parfois orteils, nez, oreilles ; <br><strong>Phases :</strong> phase blanche syncopale, puis cyanique, puis érythémateuse</td>\n            <td>Crise de <span class=\"kw-chiffre\">quelques minutes à 30 min</span>, parfois quelques heures</td>\n            <td>Examen <span class=\"kw-clinique\">normal entre les crises</span> ; pas de <span class=\"kw-clinique\">trouble trophique</span> dans la forme primitive</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Acrocyanose</span></td>\n            <td><span class=\"kw-clinique\">Femme mince</span>, début à l'adolescence ; favorisée par <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">troubles du comportement alimentaire</span>, le faible IMC, la dénutrition du sujet âgé</td>\n            <td><strong>Coloration :</strong> extrémités froides et moites, érythrosiques ou bleutées/violacées, parfois œdématiées ; <br><strong>Caractères :</strong> permanente, disparaît à la vitropression, majorée par le froid et la déclivité ; <br><strong>Associations :</strong> <span class=\"kw-clinique\">livedo</span> de stase déclive, hyperhidrose</td>\n            <td><span class=\"kw-clinique\">Permanente</span> (non paroxystique)</td>\n            <td><span class=\"kw-clinique\">Indolore</span> ; <span class=\"kw-alerte\">absence de phase blanche syncopale</span> — c'est ce qui la distingue du Raynaud</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Érythermalgie</span></td>\n            <td>Forme primitive : <span class=\"kw-clinique\">homme &lt; 40 ans</span>, atteinte symétrique, ATCD familiaux ; forme secondaire : homme ou femme &gt; <span class=\"kw-chiffre\">40 ans</span></td>\n            <td><strong>Crise :</strong> extrémités (surtout <span class=\"kw-clinique\">les</span> pieds) rouges, chaudes, intensément douloureuses ; <br><strong>Facteurs déclenchants :</strong> chaleur, exercice, orthostatisme ; <br><strong>Facteurs calmants :</strong> froid, repos, élévation du membre</td>\n            <td><span class=\"kw-clinique\">Paroxystique</span> — crise de <span class=\"kw-chiffre\">quelques minutes à quelques heures</span></td>\n            <td>Pas de <span class=\"kw-clinique\">pâleur</span> ni de <span class=\"kw-clinique\">cyanose</span> ; rougeur isolée du territoire concerné</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Engelure</span></td>\n            <td><span class=\"kw-clinique\">Femme jeune / adolescente</span>, ± <span class=\"kw-etio\">anorexique ou sous-alimentée</span> ; survenue saisonnière (automne, hiver)</td>\n            <td><strong>Lésions :</strong> maculo-papules violacées ± œdémateuses, multiples, parfois confluentes en plaques ; <br><strong>Topographie :</strong> dos des doigts et des orteils, bords latéraux des pieds, région achilléenne, hélix du nez ; <br><strong>Symptômes :</strong> douloureuses (brûlure) et prurigineuses au réchauffement</td>\n            <td>Régression spontanée en <span class=\"kw-chiffre\">2-3 semaines</span> ± dyschromie séquellaire ; récidives saisonnières</td>\n            <td>Contexte de <span class=\"kw-clinique\">froid modéré humide</span> ; pas de phase blanche syncopale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Ischémie digitale permanente</span></td>\n            <td>Contexte d'<span class=\"kw-etio\">artériopathie</span>, de <span class=\"kw-etio\">tabagisme</span>, de <span class=\"kw-clinique\">sclérodermie</span> ou de cause emboligène</td>\n            <td><strong>Doigt :</strong> froid, douloureux, blanc ou cyanique ; <br><strong>Signes :</strong> <span class=\"kw-clinique\">hémorragies sous-unguéales</span> en flammèche, temps de recoloration pulpaire allongé ; <br><strong>Trophicité :</strong> <span class=\"kw-clinique\">infarctus</span> péri-unguéal, <span class=\"kw-clinique\">ulcération</span>, nécrose digitale</td>\n            <td>Paroxysmes syncopaux, puis semi-permanente, puis permanente ; douleurs surtout nocturnes</td>\n            <td><span class=\"kw-alerte\">Urgence</span> — risque d'infection locale et d'<span class=\"kw-clinique\">évolution</span> vers la <span class=\"kw-clinique\">gangrène</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <img src=\"../assets/images/239/ischemie-digitale.jpg\" alt=\"Ischémie digitale permanente : doigt froid et cyanique avec trouble trophique pulpaire débutant\">\n      <em>Ischémie digitale permanente : doigt douloureux, froid, cyanique, avec <span class=\"kw-clinique\">trouble trophique</span> pulpaire — <span class=\"kw-alerte\">urgence</span> en raison du risque de <span class=\"kw-clinique\">nécrose</span>.</em>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> 3 phases du <span class=\"kw-clinique\">phénomène de Raynaud</span></strong> — seule la phase blanche est indispensable au diagnostic :</p>\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Sémiologie</th><th>Constance</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Phase blanche (syncopale)</td>\n            <td>Doigts <span class=\"kw-clinique\"><strong>blancs, exsangues, à limites très nettes</strong></span> ; sensation de doigts morts, insensibles, parfois douloureux</td>\n            <td><span class=\"kw-alerte\"><strong>Inaugurale et obligatoire</strong></span></td>\n          </tr>\n          <tr>\n            <td>Phase cyanique (asphyxique)</td>\n            <td>Aspect <span class=\"kw-clinique\">bleuté, violacé</span> ; dysesthésies</td>\n            <td>Inconstante</td>\n          </tr>\n          <tr>\n            <td>Phase érythémateuse (hyperhémique)</td>\n            <td><span class=\"kw-clinique\">Recoloration rouge</span> avec réchauffement ; dysesthésies souvent douloureuses</td>\n            <td>Inconstante</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Confirmation diagnostique.</strong> Le diagnostic d'un <span class=\"kw-clinique\">phénomène de Raynaud</span> repose sur l'<span class=\"kw-clinique\">interrogatoire</span>, conforté par des <span class=\"kw-clinique\">photographies de la crise prises par le patient</span>. Le <span class=\"kw-alerte\">test au froid est abandonné</span> : il n'est ni sensible ni spécifique.\n      </div>","frequence":5},{"id":"239-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques permettant de distinguer Raynaud primitif et secondaire","contenu":"<p>Devant un <span class=\"kw-clinique\">phénomène de Raynaud</span>, la question décisive est : <strong>primitif ou secondaire ?</strong> La <span class=\"kw-def\">maladie de Raynaud</span> (forme primitive ou essentielle) représente <span class=\"kw-chiffre\">80 à 90 %</span> des cas — elle est bénigne et ne se complique <span class=\"kw-ci\">jamais de</span> <span class=\"kw-clinique\">trouble trophique</span>. La démarche consiste à <strong>rechercher activement <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">drapeaux rouges</span></strong> d'une cause secondaire avant de conclure au caractère primitif.</p>\n\n      <table >\n        <thead>\n          <tr><th>Critères</th><th>Maladie de Raynaud (primitif)</th><th>Phénomène de Raynaud secondaire</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Terrain</span></td>\n            <td><span class=\"kw-clinique\">Femme jeune</span>, sex-ratio <span class=\"kw-chiffre\">4 femmes / 1 homme</span> ; <span class=\"kw-etio\">antécédents familiaux</span> fréquents</td>\n            <td>Homme ou femme, tout âge ; absence d'<span class=\"kw-etio\">antécédents familiaux</span></td>\n          </tr>\n          <tr>\n            <td>Âge de début</td>\n            <td>Avant <span class=\"kw-chiffre\">35-40 ans</span>, le plus souvent à l'adolescence</td>\n            <td>Souvent après <span class=\"kw-chiffre\">40 ans</span></td>\n          </tr>\n          <tr>\n            <td>Facteur déclenchant</td>\n            <td><span class=\"kw-clinique\">Froid</span>, variations de température, stress ; recrudescence hivernale</td>\n            <td>Pas de facteur déclenchant <span class=\"kw-alerte\">net</span> ; survenue spontanée possible</td>\n          </tr>\n          <tr>\n            <td>Distribution</td>\n            <td>Bilatérale et symétrique ; <span class=\"kw-alerte\">épargne les pouces</span></td>\n            <td>Unilatérale ou asymétrique ; <span class=\"kw-alerte\">atteinte des pouces</span></td>\n          </tr>\n          <tr>\n            <td>Description des phases</td>\n            <td>Succession des <span class=\"kw-chiffre\">3 phases</span></td>\n            <td>Phase hyperhémique souvent absente</td>\n          </tr>\n          <tr>\n            <td>Troubles trophiques</td>\n            <td>Absents</td>\n            <td><span class=\"kw-alerte\">Présents</span> — ulcérations pulpaires, cicatrices rétractiles, doigts scléreux</td>\n          </tr>\n          <tr>\n            <td>Examen physique</td>\n            <td><span class=\"kw-clinique\">Normal hors crise</span> ; tous <span class=\"kw-clinique\">les</span> pouls perçus</td>\n            <td>Anomalies — abolition d'un pouls, <span class=\"kw-clinique\">asymétrie</span> tensionnelle, souffle vasculaire</td>\n          </tr>\n          <tr>\n            <td>Manœuvre d'Allen</td>\n            <td><span class=\"kw-clinique\">Négative</span></td>\n            <td><span class=\"kw-alerte\">Positive</span></td>\n          </tr>\n          <tr>\n            <td>Capillaroscopie péri-unguéale</td>\n            <td><span class=\"kw-bio\">Normale</span></td>\n            <td><span class=\"kw-bio\">Anormale</span> — mégacapillaires, raréfaction capillaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Anticorps anti-nucléaires</span></td>\n            <td><span class=\"kw-bio\">Négatifs</span></td>\n            <td><span class=\"kw-bio\">Positifs</span> en cas de connectivite associée</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Pronostic</span></td>\n            <td><span class=\"kw-clinique\">Excellent</span></td>\n            <td>Fonction de la cause</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeaux rouges</span> — suspecter un Raynaud secondaire.</strong>\n        <ul>\n          <li>Début <span class=\"kw-chiffre\">tardif après 40 ans</span> ou sexe <strong>masculin</strong></li>\n          <li>Atteinte <span class=\"kw-alerte\">unilatérale ou asymétrique</span>, avec <span class=\"kw-alerte\">atteinte des pouces</span></li>\n          <li><span class=\"kw-alerte\">Troubles trophiques pulpaires</span> : ulcérations, cicatrices rétractiles</li>\n          <li>Signes de <span class=\"kw-etio\">connectivite</span> : doigts boudinés, <span class=\"kw-clinique\">télangiectasies</span>, sclérodactylie</li>\n          <li>Anomalies vasculaires : abolition d'un pouls, <span class=\"kw-clinique\">asymétrie</span> tensionnelle, souffle</li>\n          <li>Anomalies à la <span class=\"kw-bio\">capillaroscopie péri-unguéale</span></li>\n        </ul>\n      </div>\n\n      <p><strong>Étiologies du <span class=\"kw-clinique\">phénomène de Raynaud</span> secondaire :</strong></p>\n      <table >\n        <thead>\n          <tr><th>Famille étiologique</th><th>Exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Connectivites / MAI systémiques</td>\n            <td><span class=\"kw-etio\"><strong>Sclérodermie systémique</strong></span> (le Raynaud peut <span class=\"kw-alerte\">précéder les autres signes de 10 ans</span>) ; <span class=\"kw-etio\">lupus systémique</span> ; <span class=\"kw-etio\">syndrome de Sjögren</span> ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span> ; <span class=\"kw-etio\">connectivite mixte (syndrome de Sharp)</span> ; <span class=\"kw-etio\">dermatomyosite</span></td>\n          </tr>\n          <tr>\n            <td>Causes locorégionales</td>\n            <td><span class=\"kw-etio\">Syndrome du marteau hypothénar</span> (anévrisme de l'artère ulnaire) ; <span class=\"kw-etio\">maladies professionnelles des engins vibrants</span> (tableau n°69) ; <span class=\"kw-etio\">syndrome du canal carpien</span></td>\n          </tr>\n          <tr>\n            <td>Sténose / obstruction artérielle</td>\n            <td><span class=\"kw-etio\">Syndrome de la traversée thoraco-brachiale</span> (côte surnuméraire) ; artériopathies inflammatoires (<span class=\"kw-etio\">Takayasu</span>, <span class=\"kw-etio\">artérite à cellules géantes</span>, <span class=\"kw-etio\">maladie de Buerger</span>) ou non inflammatoires</td>\n          </tr>\n          <tr>\n            <td>Toxiques</td>\n            <td><span class=\"kw-etio\">Tabac</span> ; <span class=\"kw-etio\">cannabis</span> ; <span class=\"kw-etio\">cocaïne</span> ; <span class=\"kw-etio\">amphétamines</span> ; <span class=\"kw-etio\">arsenic</span></td>\n          </tr>\n          <tr>\n            <td>Médicaments</td>\n            <td><span class=\"kw-ci\">β-bloquants</span> (y compris en collyre) ; <span class=\"kw-ci\">dérivés de l'ergot de seigle</span> ; <span class=\"kw-ci\">triptans</span> ; <span class=\"kw-ci\">sympathomimétiques nasaux</span> ; <span class=\"kw-ci\">bléomycine</span> ; <span class=\"kw-ci\">interféron</span> ; <span class=\"kw-ci\">bromocriptine</span> ; <span class=\"kw-ci\">gemcitabine</span> ; <span class=\"kw-ci\">vinblastine</span> ; <span class=\"kw-ci\">amantadine</span></td>\n          </tr>\n          <tr>\n            <td>Endocrinien / autres</td>\n            <td><span class=\"kw-etio\">Hypothyroïdie</span> ; rang C : cryoglobulinémie, maladie des agglutinines froides, syndrome myéloprolifératif</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-clinique\">Sclérodermie</span> systémique — le piège majeur.</strong> Le <span class=\"kw-clinique\">phénomène de Raynaud</span> y est souvent <strong>inaugural</strong> et peut <span class=\"kw-alerte\">précéder de 10 ans</span> l'apparition des autres signes. Tout Raynaud suspect de secondaire impose un <span class=\"kw-clinique\">suivi clinique prolongé</span> avant de conclure à une maladie de Raynaud primitive.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-def\">Vascularite</span> systémique · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 195 — Artérite à cellules géantes · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 75 — Addiction <span class=\"kw-etio\">Tabac</span></em></p>","frequence":17},{"id":"239-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes dermatologiques de la sclérodermie systémique (hors Raynaud)","contenu":"<p>La <span class=\"kw-etio\"><strong>sclérodermie systémique</strong></span> est la principale cause de <span class=\"kw-def\">phénomène de Raynaud secondaire</span>. Ses <span class=\"kw-clinique\">signes dermatologiques</span> extra-Raynaud sont <strong>précoces</strong> et orientent fortement le diagnostic dès l'<span class=\"kw-clinique\">inspection des mains</span>.</p>\n\n      <img src=\"../assets/images/239/sclerodactylie.jpg\" alt=\"Sclérodactylie : doigts effilés à peau scléreuse et tendue chez un patient atteint de sclérodermie systémique\">\n      <em><span class=\"kw-clinique\">Sclérodactylie</span> : doigts effilés, peau scléreuse et tendue, effacement des plis cutanés — signe dermatologique majeur de la <span class=\"kw-clinique\">sclérodermie</span> systémique.</em>\n\n      <table >\n        <thead>\n          <tr><th>Signe</th><th>Description sémiologique et valeur diagnostique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Hémorragies en flammèche</span></td>\n            <td><span class=\"kw-clinique\">Hémorragies du lit capillaire sous-unguéal</span>, visibles à l'œil nu</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Hypertrophie cuticulaire</span></td>\n            <td><span class=\"kw-clinique\">Hypertrophie de la cuticule de l'ongle</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Ulcérations pulpaires</span></td>\n            <td><span class=\"kw-alerte\">Ulcération distale et cicatrices rétractiles pulpaires</span> — <span class=\"kw-clinique\">trouble trophique</span> évolué</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Sclérodactylie</span></td>\n            <td><span class=\"kw-def\">Doigts boudinés ou scléreux</span> ; la <span class=\"kw-clinique\">sclérose cutanée</span> peut aussi atteindre le tronc et le visage</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Télangiectasies</span></td>\n            <td><span class=\"kw-def\">Ectasies vasculaires cutanées</span> — surtout aux <span class=\"kw-clinique\">extrémités</span>, sur le <span class=\"kw-clinique\">visage</span> et le décolleté</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Calcinose</span></td>\n            <td><span class=\"kw-def\">Calcinose sous-cutanée</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Paysage sclérodermique en capillaroscopie péri-unguéale :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\"><strong>Mégacapillaires</strong></span> (ectasies) — observés dans <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">connectivites</span>, surtout la <span class=\"kw-etio\">sclérodermie systémique</span>, la <span class=\"kw-etio\">connectivite mixte</span> et la <span class=\"kw-etio\">dermatomyosite</span></li>\n        <li><span class=\"kw-bio\">Raréfaction</span> capillaire voire <span class=\"kw-alerte\">désert capillaire</span> — au cours de la <span class=\"kw-etio\">sclérodermie systémique avancée</span></li>\n        <li>L'association de ces anomalies définit le <span class=\"kw-def\">« paysage sclérodermique »</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Raynaud isolé prolongé.</strong> La <span class=\"kw-etio\">sclérodermie systémique</span> peut débuter par un <span class=\"kw-alerte\">phénomène de Raynaud isolé pendant 10 ans</span> avant l'apparition des autres signes. D'où l'importance d'un <span class=\"kw-clinique\">suivi clinique annuel</span> chez tout patient présentant un Raynaud suspect.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-def\">Vascularite</span> systémique · 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":8},{"id":"239-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de réalisation d’une manœuvre d’Allen","contenu":"<p><strong>Objectif du test.</strong> La <span class=\"kw-def\">manœuvre d'Allen</span> explore la <span class=\"kw-clinique\">perméabilité des artères digitales</span> et le fonctionnement des <span class=\"kw-clinique\">arcades palmaires</span> (superficielle et profonde).</p>\n\n      <p><strong>Réalisation, en 3 temps :</strong></p>\n      <ol>\n        <li>Comprimer <strong>simultanément</strong> <span class=\"kw-clinique\">les</span> artères <span class=\"kw-clinique\">radiale et ulnaire</span> au niveau du poignet (les pouls sont présents avant compression).</li>\n        <li>Demander au patient des mouvements de <span class=\"kw-clinique\">flexion-extension des doigts</span> jusqu'à ce que la main se <span class=\"kw-clinique\">décolore</span>.</li>\n        <li>Relâcher la pression sur <strong>une artère à la fois</strong> et vérifier que la main se <span class=\"kw-clinique\">recolore en quelques secondes</span> (hyperémie réactionnelle post-occlusive).</li>\n      </ol>\n\n      <table >\n        <thead>\n          <tr><th>Résultat</th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Manœuvre normale</td>\n            <td><span class=\"kw-clinique\">Recoloration rapide</span> (quelques secondes), homogène, de la paume vers <span class=\"kw-clinique\">les</span> pulpes digitales</td>\n          </tr>\n          <tr>\n            <td>Manœuvre anormale</td>\n            <td><span class=\"kw-alerte\">Retard ou absence de recoloration</span> d'un ou plusieurs doigts → ischémie distale objectivée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Interprétation topographique :</strong> le relâchement de l'artère <span class=\"kw-clinique\">ulnaire</span> teste l'<span class=\"kw-def\">arcade palmaire superficielle</span> ; le relâchement de l'artère <span class=\"kw-clinique\">radiale</span> teste l'<span class=\"kw-def\">arcade palmaire profonde</span>. La manœuvre permet aussi d'approcher la topographie des lésions (atteinte uni- ou bilatérale, territoire radial ou ulnaire).</p>\n\n      <p><strong>Indications :</strong> recherche d'un <span class=\"kw-clinique\">Raynaud secondaire</span> (une manœuvre d'Allen positive est un <span class=\"kw-alerte\">drapeau rouge</span>), exploration d'une <span class=\"kw-clinique\">artériopathie distale</span>, et bilan préalable à un <span class=\"kw-bio\">prélèvement de gaz du sang artériel</span> ou à un cathétérisme radial — pour <span class=\"kw-ci\">ne jamais</span> ponctionner une radiale qui serait la seule artère perméable.</p>","frequence":1},{"id":"239-6","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies de phénomène de Raynaud (phase syncopale)","contenu":"<img src=\"../assets/images/239/raynaud-phase-syncopale.jpg\" alt=\"Phénomène de Raynaud en phase syncopale : plusieurs phalanges blanches et exsangues aux limites nettes\">\n      <em>Phase syncopale (blanche) d'un <span class=\"kw-clinique\">phénomène de Raynaud</span> : doigts blancs, exsangues, aux limites très nettes — l'image diagnostique de référence.</em>\n\n      <p>La <span class=\"kw-clinique\"><strong>phase blanche, dite syncopale</strong></span>, est la phase <span class=\"kw-clinique\"><strong>inaugurale</strong></span> et la <span class=\"kw-alerte\">seule phase indispensable au diagnostic</span> : <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">deux phases</span> suivantes sont inconstantes.</p>\n      <ul>\n        <li>Doigts <span class=\"kw-clinique\"><strong>blancs, exsangues</strong></span>, à <span class=\"kw-alerte\">limites très nettes</span> (caractère très évocateur)</li>\n        <li>Sensation de <span class=\"kw-clinique\">doigts morts, insensibles</span>, parfois <span class=\"kw-clinique\">douloureux</span></li>\n        <li>Touche <span class=\"kw-clinique\">une ou plusieurs phalanges</span> — pas toujours <span class=\"kw-clinique\">les</span> mêmes d'une crise à l'autre, parfois <span class=\"kw-clinique\">orteils, nez, oreilles</span></li>\n        <li>Durée : de <span class=\"kw-chiffre\">quelques minutes à quelques heures</span></li>\n      </ul>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> deux phases suivantes, inconstantes :</strong> la <span class=\"kw-clinique\">phase cyanique (asphyxique)</span> donne un <span class=\"kw-clinique\">aspect bleuté, violacé</span> avec <span class=\"kw-clinique\">dysesthésies</span> ; la <span class=\"kw-clinique\">phase érythémateuse (hyperhémique)</span> correspond à la <span class=\"kw-clinique\">recoloration rouge</span>, avec réchauffement et <span class=\"kw-clinique\">dysesthésies douloureuses</span>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Confirmation diagnostique.</strong> Le diagnostic repose sur l'<span class=\"kw-clinique\">interrogatoire</span> ; il est conforté par des <span class=\"kw-clinique\">photographies de la crise prises par le patient</span>. Le <span class=\"kw-alerte\">test au froid est abandonné</span> : il n'est ni sensible ni spécifique.\n      </div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/raynaud-phenomenon","label":"Radiopaedia : Raynaud phenomenon"}]},{"id":"239-7","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’engelure","contenu":"<img src=\"../assets/images/239/engelures-orteils.jpg\" alt=\"Engelures aux orteils : maculo-papules violacées et œdémateuses après exposition au froid humide\">\n      <em>Engelures des orteils : maculo-papules violacées, œdémateuses, douloureuses et prurigineuses au réchauffement.</em>\n\n      <p>L'<span class=\"kw-def\"><strong>engelure</strong></span> est un <span class=\"kw-def\">acrosyndrome vasculaire à composante trophique</span>, le plus souvent primitif, déclenché par le <span class=\"kw-clinique\">froid humide</span>.</p>\n\n      <p><strong>Sémiologie typique :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Macules érythémateuses</span>, puis <span class=\"kw-clinique\"><strong>maculo-papules violacées</strong></span>, parfois <span class=\"kw-clinique\">œdémateuses</span></li>\n        <li>Topographie : <span class=\"kw-clinique\">dos des doigts et des orteils</span>, <span class=\"kw-clinique\">bords latéraux des pieds</span>, région achilléenne, hélix du nez</li>\n        <li><span class=\"kw-clinique\"><strong>Douloureuses</strong></span> (brûlure) et <span class=\"kw-alerte\">prurigineuses au réchauffement</span> — caractère particulièrement évocateur</li>\n        <li>Lésions multiples, parfois confluentes en <span class=\"kw-clinique\">plaques érythrocyaniques</span></li>\n      </ul>\n\n      <p><strong>Contexte de survenue :</strong> <span class=\"kw-clinique\">femme jeune</span> (adolescente, ± <span class=\"kw-etio\">anorexique ou sous-alimentée</span>), exposition à un <span class=\"kw-clinique\">froid modéré</span> (<span class=\"kw-chiffre\">8-10 °C</span>) mais <span class=\"kw-alerte\">humide</span> ; récidives <span class=\"kw-clinique\">saisonnières</span> (automne, hiver).</p>\n\n      <p><strong><span class=\"kw-clinique\">Évolution</span> :</strong> <span class=\"kw-clinique\">régression spontanée</span> en <span class=\"kw-chiffre\">2-3 semaines</span>, parfois avec <span class=\"kw-clinique\">dyschromie séquellaire</span> ; complications possibles — <span class=\"kw-alerte\">bulles hémorragiques, exulcérations</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span> — <span class=\"kw-def\">lupus</span>-engelures.</strong> Si <span class=\"kw-clinique\">les</span> engelures <span class=\"kw-alerte\">apparaissent tardivement</span> ou <span class=\"kw-alerte\">persistent en période estivale</span>, il faut évoquer le <span class=\"kw-etio\">lupus-engelures</span> (forme particulière de <span class=\"kw-def\">lupus</span> érythémateux) et doser les <span class=\"kw-bio\">anticorps anti-nucléaires</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":1},{"id":"239-8","rang":"B","rubrique":"Contenu multimédia","titre":"Vidéo ou photographies de manœuvre d’Allen","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune vidéo ni photographie de <span class=\"kw-def\">manœuvre d'Allen</span> n'est disponible dans le repo (<code>assets/images/239/</code>). Kevin enrichira cet objectif manuellement avec une iconographie pédagogique (Pilly, Collège de Médecine Vasculaire, vidéo éducative annotée) ou une démonstration filmée.\n      </div>\n\n      <p>En attendant, voici la <strong>sémiologie attendue</strong> d'une manœuvre d'Allen filmée — la procédure complète est détaillée dans l'objectif « modalités de réalisation d'une manœuvre d'Allen » :</p>\n      <ul>\n        <li><strong>Temps 0 :</strong> main au repos, <span class=\"kw-clinique\">coloration rose homogène</span></li>\n        <li><strong>Temps 1 :</strong> <span class=\"kw-clinique\">compression du poignet</span> (artères <span class=\"kw-clinique\">radiale et ulnaire</span>) et <span class=\"kw-clinique\">mouvements de flexion-extension</span> — la main <span class=\"kw-clinique\">blanchit</span> jusqu'à devenir <span class=\"kw-clinique\">exsangue</span></li>\n        <li><strong>Temps 2 :</strong> relâchement d'une artère — <span class=\"kw-clinique\">recoloration rapide</span> (test négatif) ou <span class=\"kw-alerte\">retard / absence de recoloration</span> d'un ou plusieurs doigts (test positif, pathologique)</li>\n      </ul>\n\n      <p><strong>Utilité diagnostique</strong> (cf. objectif manœuvre d'Allen pour le détail) : recherche d'un <span class=\"kw-clinique\">Raynaud secondaire</span>, exploration d'une <span class=\"kw-clinique\">artériopathie distale</span>, et sécurité avant un <span class=\"kw-bio\">prélèvement de gaz du sang artériel</span> ou un <span class=\"kw-bio\">cathétérisme radial</span>.</p>","frequence":0},{"id":"239-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication de la réalisation d’anticorps anti-nucléaires (AAN) et de la capillaroscopie","contenu":"<p>Devant un <span class=\"kw-clinique\">phénomène de Raynaud</span>, la <span class=\"kw-def\">stratégie diagnostique est clinique</span>. <span class=\"kw-clinique\">Les</span> examens complémentaires — <span class=\"kw-bio\">anticorps anti-nucléaires (AAN)</span> et <span class=\"kw-bio\">capillaroscopie péri-unguéale</span> — ne sont indiqués qu'en cas d'<strong>atypie clinique</strong> évoquant une cause secondaire. Devant un Raynaud typiquement primitif, sans aucun signe d'appel, aucun examen n'est nécessaire.</p>\n\n      <table >\n        <thead>\n          <tr><th>Atypie clinique</th><th>Précision — <span class=\"kw-alerte\">drapeau rouge</span> imposant <span class=\"kw-bio\">AAN</span> + capillaroscopie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Début tardif</td><td>Survenue du <span class=\"kw-clinique\">phénomène de Raynaud</span> <span class=\"kw-chiffre\">après 40 ans</span></td></tr>\n          <tr><td>Sexe masculin</td><td>La <span class=\"kw-def\">maladie de Raynaud</span> touche préférentiellement la femme jeune</td></tr>\n          <tr><td>Atteinte asymétrique</td><td><span class=\"kw-clinique\">Phénomène de Raynaud</span> <span class=\"kw-clinique\">unilatéral ou asymétrique</span></td></tr>\n          <tr><td>Atteinte des pouces</td><td><span class=\"kw-clinique\">Les</span> pouces sont normalement <span class=\"kw-clinique\">épargnés</span> dans la forme primitive</td></tr>\n          <tr><td>Troubles trophiques</td><td><span class=\"kw-alerte\">Ulcérations ou cicatrices rétractiles pulpaires</span></td></tr>\n          <tr><td>Anomalie d'Allen</td><td><span class=\"kw-clinique\">Manœuvre d'Allen pathologique</span></td></tr>\n          <tr><td>Anomalies vasculaires</td><td><span class=\"kw-clinique\">Abolition d'un pouls</span>, <span class=\"kw-clinique\">asymétrie tensionnelle</span>, <span class=\"kw-clinique\">souffle vasculaire</span></td></tr>\n          <tr><td>Signes de connectivite</td><td><span class=\"kw-etio\">Doigts boudinés</span>, <span class=\"kw-etio\">télangiectasies</span>, <span class=\"kw-etio\">sclérodactylie</span>, <span class=\"kw-clinique\">hémorragies sous-unguéales en flammèche</span></td></tr>\n          <tr><td>Engelure atypique</td><td>Survenue tardive ou persistance estivale → suspicion de <span class=\"kw-etio\">lupus-engelures</span></td></tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Anomalie capillaroscopique</th><th>Pathologie évoquée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Mégacapillaires (ectasies)</td>\n            <td><span class=\"kw-etio\">Sclérodermie systémique</span>, <span class=\"kw-etio\">connectivite mixte</span>, <span class=\"kw-etio\">dermatomyosite</span></td>\n          </tr>\n          <tr>\n            <td>Raréfaction / désert capillaire</td>\n            <td><span class=\"kw-alerte\">Sclérodermie systémique avancée</span></td>\n          </tr>\n          <tr>\n            <td>« Paysage sclérodermique »</td>\n            <td><span class=\"kw-def\">Association mégacapillaires + raréfaction + microhémorragies</span> — hautement évocatrice d'une <span class=\"kw-etio\">sclérodermie systémique</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong><span class=\"kw-bio\">Anticorps anti-nucléaires</span> (<span class=\"kw-bio\">AAN</span>).</strong> Ils sont <span class=\"kw-bio\">positifs</span> en cas de <span class=\"kw-etio\">connectivite associée</span> (<span class=\"kw-def\">lupus</span> systémique, <span class=\"kw-clinique\">sclérodermie</span>, <span class=\"kw-clinique\">syndrome de Sjögren</span>). Ils sont <span class=\"kw-bio\">négatifs</span> dans la <span class=\"kw-def\">maladie de Raynaud primitive</span> — leur positivité réoriente donc vers une cause secondaire.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Selon l'acrosyndrome.</strong> Devant une <span class=\"kw-clinique\">érythermalgie</span>, une <span class=\"kw-bio\">NFS</span> est systématique (recherche d'un <span class=\"kw-etio\">syndrome myéloprolifératif</span> — <span class=\"kw-etio\">thrombocytémie essentielle, polyglobulie primitive</span>). Devant une <span class=\"kw-clinique\">ischémie digitale permanente</span>, le bilan associe capillaroscopie, <span class=\"kw-bio\">écho-doppler artériel</span> et recherche d'étiologie systémique (cryoglobulinémie, anévrisme, cause <span class=\"kw-etio\">paranéoplasique</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-def\">Vascularite</span> systémique · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 213 — Anémie</em></p>","frequence":4}],"astuces":[],"strategie":{"urgence":"<p><strong>Ischémie digitale permanente <span class=\"q\">— <span class=\"kw-alerte\">urgence</span>, risque de <span class=\"kw-clinique\">nécrose</span></span></strong></p><p><span class=\"kw-ttt\">Revascularisation</span> sans délai + bilan étiologique en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-bio\">capillaroscopie</span>, <span class=\"kw-imagerie\">écho-doppler artériel</span>)</p><ul><li>Doigt <span class=\"kw-clinique\">froid, douloureux, blanc ou cyanique</span> ; <span class=\"kw-clinique\">temps de recoloration pulpaire allongé</span></li><li><span class=\"kw-clinique\">Hémorragies sous-unguéales en flammèche</span> ; douleurs surtout <span class=\"kw-clinique\">nocturnes</span></li><li>Sans <span class=\"kw-ttt\">revascularisation</span> rapide → <span class=\"kw-alerte\">infarctus péri-unguéal</span>, <span class=\"kw-alerte\">ulcération</span>, <span class=\"kw-alerte\">nécrose digitale</span>, <span class=\"kw-alerte\">gangrène</span>, <span class=\"kw-alerte\">infection locale</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Ischémie digitale permanente</span> : doigt froid cyanique avec <span class=\"kw-clinique\">trouble trophique</span> → <span class=\"kw-alerte\">urgence</span> (risque de <span class=\"kw-alerte\">nécrose</span>)</li><li>Raynaud à <span class=\"kw-alerte\">début tardif (&gt; 40 ans)</span> ou chez l'<span class=\"kw-alerte\">homme</span></li><li>Raynaud <span class=\"kw-alerte\">unilatéral / asymétrique</span> avec <span class=\"kw-alerte\">atteinte des pouces</span></li><li><span class=\"kw-alerte\">Troubles trophiques pulpaires</span> : ulcérations, cicatrices rétractiles</li><li>Signes de <span class=\"kw-etio\">connectivite</span> : <span class=\"kw-clinique\">doigts boudinés</span>, <span class=\"kw-clinique\">télangiectasies</span>, <span class=\"kw-clinique\">sclérodactylie</span></li><li>Anomalies vasculaires : <span class=\"kw-clinique\">abolition d'un pouls</span>, <span class=\"kw-clinique\">asymétrie tensionnelle</span>, <span class=\"kw-clinique\">souffle vasculaire</span></li><li><span class=\"kw-bio\">Capillaroscopie péri-unguéale anormale</span> (mégacapillaires, raréfaction capillaire)</li><li><span class=\"kw-def\">Engelures</span> tardives ou persistant en période estivale → suspecter un <span class=\"kw-etio\">lupus-engelures</span></li></ul>","principes":"<p>La PEC associe le <span class=\"kw-ttt\">traitement étiologique</span> (Raynaud secondaire), la <span class=\"kw-ttt\">suppression des facteurs favorisants</span> et la <span class=\"kw-ttt\">protection contre le froid</span>. Le <span class=\"kw-ttt\">traitement médicamenteux</span> est réservé aux <span class=\"kw-alerte\">formes sévères</span> et aux Raynaud secondaires (rang C).</p><p><strong>Mesures générales <span class=\"q\">(tout acrosyndrome)</span></strong></p><ul><li><span class=\"kw-ttt\">Protection vestimentaire</span> et <span class=\"kw-ttt\">non-exposition au froid</span> (+++)</li><li><span class=\"kw-ttt\">Suppression des facteurs favorisants</span> : <span class=\"kw-ci\">tabac</span>, <span class=\"kw-ci\">cannabis</span>, <span class=\"kw-ci\">β-bloquants</span> (même en collyre), <span class=\"kw-ci\">dérivés de l'ergot de seigle</span>, <span class=\"kw-ci\">triptans</span></li></ul><p><strong>Maladie de Raynaud <span class=\"q\">(primitive, bénigne)</span></strong></p><ul><li>Forme bénigne ne se compliquant <span class=\"kw-ci\">jamais de</span> <span class=\"kw-clinique\">trouble trophique</span> → <span class=\"kw-ttt\">mesures non médicamenteuses</span> suffisantes dans la majorité des cas</li><li>Évaluer le <span class=\"kw-clinique\">retentissement</span> des crises sur la vie quotidienne</li></ul><p><strong>Raynaud secondaire / formes sévères</strong></p><p><span class=\"kw-ttt\">Traitement étiologique</span> de la cause sous-jacente</p><ul><li><span class=\"kw-ttt\">Inhibiteurs calciques per os</span> (<span class=\"kw-ttt\">nifédipine</span>, <span class=\"kw-ttt\">amlodipine</span>)</li><li><span class=\"kw-ttt\">Perfusions IV d'iloprost</span> (analogue de la prostacycline) dans <span class=\"kw-clinique\">les</span> formes sévères / <span class=\"kw-etio\">sclérodermie</span></li></ul><p><strong>Érythermalgie</strong></p><ul><li>Soulagement par le <span class=\"kw-ttt\">froid</span>, le repos, l'élévation du membre</li><li><span class=\"kw-ttt\">Aspirine</span> surtout efficace dans <span class=\"kw-clinique\">les</span> érythermalgies <span class=\"kw-etio\">secondaires aux hémopathies</span></li></ul>","suivi":"<p><strong>Maladie de Raynaud :</strong> <span class=\"kw-def\">suivi</span> clinique pour confirmer le caractère primitif — <span class=\"kw-chiffre\">≥ 2 ans</span> sans apparition d'une autre cause.<br><strong>Raynaud suspect de secondaire :</strong> <span class=\"kw-clinique\">suivi clinique prolongé</span> car la <span class=\"kw-etio\">sclérodermie systémique</span> peut être précédée d'un Raynaud isolé pendant <span class=\"kw-chiffre\">10 ans</span> ; répéter <span class=\"kw-bio\">AAN</span> et <span class=\"kw-bio\">capillaroscopie</span> au moindre signe d'appel.<br><strong>Engelure :</strong> récidives <span class=\"kw-clinique\">saisonnières</span> fréquentes ; doser <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">AAN</span> si survenue tardive ou persistance estivale (<span class=\"kw-etio\">lupus-engelures</span>).</p>"},"liensGlobaux":[{"href":"https://www.sfdermato.org/media/pdf/fmc/fmc-aout-fe2c6060be9629c71c7d5fdd456f377a.pdf","label":"Fmc aout fe2c6060be9629c71c7d5fdd456f377a"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Acrosyndrome — tri sur la signature clinique — Interrogatoire + examen + photographies de la crise prises par le patient","detail":"<h4>CAT — orientation devant un acrosyndrome — Tri sur la signature clinique, puis Raynaud primitif <span class=\"kw-bio\">vs</span> secondaire</h4>","branches":[{"to":"q-raynaud","label":"Crises paroxystiques au froid avec phase blanche syncopale","color":"blue"},{"to":"t-acrocyanose","label":"Cyanose permanente, froide, indolore, sans phase blanche","color":"green"},{"to":"t-erythermalgie","label":"Crises de rougeur chaude et douloureuse déclenchées par la chaleur","color":"amber"},{"to":"t-engelure","label":"Maculo-papules violacées après froid humide, prurigineuses au réchauffement","color":"green"},{"to":"t-ischemie","label":"Doigt froid douloureux permanent avec trouble trophique","color":"red"}]},{"id":"q-raynaud","kind":"decision","label":"Phénomène de Raynaud : drapeaux rouges de cause secondaire ? — Terrain, topographie, trophicité, examen vasculaire, capillaroscopie","branches":[{"to":"t-raynaud-primitif","label":"Aucun drapeau rouge (terrain typique, examen normal)","color":"green"},{"to":"t-raynaud-secondaire","label":"Au moins un drapeau rouge (atypie)","color":"amber"}]},{"id":"t-raynaud-primitif","kind":"terminal","label":"Maladie de Raynaud (primitive)","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">Femme jeune</span> (sex-ratio <span class=\"kw-chiffre\">4F/1H</span>), début avant <span class=\"kw-chiffre\">35-40 ans</span>, ATCD familiaux ; représente <span class=\"kw-chiffre\">80-90 %</span> des phénomènes de Raynaud</li></ul><h4>Clinique</h4><ul><li>Atteinte <span class=\"kw-clinique\">bilatérale et symétrique</span>, <span class=\"kw-clinique\">épargne des pouces</span></li><li>Succession des <span class=\"kw-chiffre\">3 phases</span> ; examen <span class=\"kw-clinique\">normal hors crise</span>, tous <span class=\"kw-clinique\">les</span> pouls perçus</li><li>Pas de <span class=\"kw-clinique\">trouble trophique</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">AAN négatifs</span>, <span class=\"kw-bio\">capillaroscopie normale</span>, <span class=\"kw-clinique\">manœuvre d'Allen négative</span> ; aucun examen nécessaire si forme typique</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Protection contre le froid</span> + <span class=\"kw-ttt\">suppression des facteurs favorisants</span> ; <span class=\"kw-def\">pronostic</span> <span class=\"kw-clinique\">excellent</span>, bénin</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Confirmer le caractère primitif : <span class=\"kw-chiffre\">≥ 2 ans</span> sans apparition d'une autre cause</li></ul>"},{"id":"t-raynaud-secondaire","kind":"terminal","label":"Phénomène de Raynaud secondaire","color":"amber","detail":"<h4><span class=\"kw-alerte\">Drapeaux rouges</span></h4><ul><li>Début <span class=\"kw-alerte\">&gt; 40 ans</span> ou sexe <span class=\"kw-alerte\">masculin</span></li><li>Atteinte <span class=\"kw-alerte\">unilatérale / asymétrique</span> avec <span class=\"kw-alerte\">atteinte des pouces</span></li><li><span class=\"kw-alerte\">Troubles trophiques pulpaires</span> ; signes de <span class=\"kw-etio\">connectivite</span> ; <span class=\"kw-clinique\">abolition d'un pouls</span>, <span class=\"kw-clinique\">souffle vasculaire</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sclérodermie systémique</span> — le Raynaud peut précéder <span class=\"kw-clinique\">les</span> autres signes de <span class=\"kw-chiffre\">10 ans</span> (piège majeur)</li><li>Autres connectivites : <span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">Sjögren</span>, <span class=\"kw-etio\">polyarthrite rhumatoïde</span>, <span class=\"kw-etio\">connectivite mixte</span>, <span class=\"kw-etio\">dermatomyosite</span></li><li>Locorégionales : <span class=\"kw-etio\">marteau hypothénar</span>, <span class=\"kw-etio\">engins vibrants</span>, <span class=\"kw-etio\">canal carpien</span></li><li>Toxiques / médicaments : <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">cannabis</span>, <span class=\"kw-ci\">β-bloquants</span>, <span class=\"kw-ci\">dérivés de l'ergot de seigle</span>, <span class=\"kw-ci\">triptans</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">AAN</span> + <span class=\"kw-bio\">capillaroscopie péri-unguéale</span> systématiques ; <span class=\"kw-imagerie\">écho-doppler des membres supérieurs</span> si <span class=\"kw-clinique\">asymétrie</span> ou Allen pathologique</li></ul><h4>Renvoi</h4><ul><li>Item 193 (<span class=\"kw-clinique\">vascularite</span> systémique) · Item 194 (lupus - SAPL) · Item 196 (polyarthrite rhumatoïde) · Item 75 (tabac)</li></ul>"},{"id":"t-acrocyanose","kind":"terminal","label":"Acrocyanose","color":"green","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Microangiopathie fonctionnelle bénigne</span> ; touche <span class=\"kw-chiffre\">10 %</span> de la population</li></ul><h4>Clinique</h4><ul><li>Extrémités <span class=\"kw-clinique\">froides, moites</span>, érythrosiques ou <span class=\"kw-clinique\">bleutées/violacées</span>, <span class=\"kw-clinique\">permanentes</span></li><li>Disparaît à la <span class=\"kw-clinique\">vitropression</span> ; majorée par le <span class=\"kw-clinique\">froid</span> et la <span class=\"kw-clinique\">déclivité</span> ; <span class=\"kw-clinique\">indolore</span></li><li><span class=\"kw-alerte\">Absence de phase blanche syncopale</span> — c'est ce qui la distingue du Raynaud</li></ul><h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">Femme mince</span>, début à l'adolescence ; si début tardif → rechercher un <span class=\"kw-etio\">amaigrissement</span> / <span class=\"kw-etio\">TCA</span> / dénutrition</li></ul><h4>Paraclinique</h4><ul><li>Diagnostic <span class=\"kw-clinique\">clinique</span> — aucun examen complémentaire nécessaire</li></ul>"},{"id":"t-erythermalgie","kind":"terminal","label":"Érythermalgie","color":"amber","detail":"<h4>Clinique</h4><ul><li>Extrémités (surtout <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">pieds</span>) <span class=\"kw-clinique\">rouges, chaudes, intensément douloureuses</span> ; crise <span class=\"kw-clinique\">paroxystique</span> calmée par le froid</li></ul><h4>Critères</h4><ul><li>3 majeurs : <span class=\"kw-clinique\">évolution</span> par crises ; douleur à type de <span class=\"kw-clinique\">brûlure</span> ; <span class=\"kw-clinique\">rougeur</span> du territoire</li><li><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> min</span>eurs : déclenchée par chaleur/exercice/orthostatisme ; calmée par froid/repos/élévation ; sensibilité à l'<span class=\"kw-ttt\">aspirine</span></li></ul><h4>Étiologies</h4><ul><li>Primitive : <span class=\"kw-clinique\">homme &lt; 40 ans</span>, atteinte symétrique, ATCD familiaux</li><li>Secondaire (&gt;<span class=\"kw-chiffre\"> 40 ans</span>) : <span class=\"kw-etio\">syndrome myéloprolifératif</span> ++ (<span class=\"kw-etio\">thrombocytémie essentielle</span>, <span class=\"kw-etio\">polyglobulie primitive</span>), <span class=\"kw-etio\">hyperthyroïdie</span>, <span class=\"kw-etio\">lupus</span>, cause <span class=\"kw-etio\">paranéoplasique</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">NFS</span> systématique (SMP dans <span class=\"kw-chiffre\">50 %</span> des cas) ; <span class=\"kw-imagerie\">écho-doppler veineux</span> si atteinte exclusive des pieds</li></ul>"},{"id":"t-engelure","kind":"terminal","label":"Engelure","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Maculo-papules violacées</span> ± œdémateuses ; dos des doigts/orteils, bords latéraux des pieds ; <span class=\"kw-clinique\">douloureuses</span> (brûlure) et <span class=\"kw-clinique\">prurigineuses au réchauffement</span></li></ul><h4>Contexte</h4><ul><li><span class=\"kw-clinique\">Femme jeune</span> ± <span class=\"kw-etio\">anorexique / sous-alimentée</span> ; <span class=\"kw-clinique\">froid modéré</span> (<span class=\"kw-chiffre\">8-10 °C</span>) mais <span class=\"kw-clinique\">humide</span> ; saisonnier (automne, hiver)</li></ul><h4><span class=\"kw-clinique\">Évolution</span></h4><ul><li>Régression spontanée en <span class=\"kw-chiffre\">2-3 semaines</span> ± dyschromie séquellaire ; récidives saisonnières ; complications : <span class=\"kw-alerte\">bulles hémorragiques</span>, <span class=\"kw-alerte\">exulcérations</span></li></ul><h4><span class=\"kw-alerte\">Drapeau rouge</span></h4><ul><li>Survenue <span class=\"kw-alerte\">tardive</span> ou <span class=\"kw-alerte\">persistance estivale</span> → évoquer un <span class=\"kw-etio\">lupus-engelures</span> → doser <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">AAN</span></li></ul><h4>Renvoi</h4><ul><li>Item 194 (<span class=\"kw-clinique\">lupus</span> - SAPL)</li></ul>"},{"id":"t-ischemie","kind":"terminal","label":"Ischémie digitale permanente (urgence)","color":"red","detail":"<h4>Présentation</h4><ul><li>Doigt <span class=\"kw-clinique\">froid, douloureux, blanc ou cyanique</span> ; <span class=\"kw-clinique\">hémorragies sous-unguéales en flammèche</span> ; <span class=\"kw-clinique\">temps de recoloration pulpaire allongé</span> ; douleurs <span class=\"kw-clinique\">nocturnes</span></li></ul><h4>Gravité</h4><ul><li><span class=\"kw-alerte\">Urgence</span> — sans <span class=\"kw-ttt\">revascularisation</span> rapide : <span class=\"kw-alerte\">infarctus péri-unguéal</span>, <span class=\"kw-alerte\">ulcération</span>, <span class=\"kw-alerte\">nécrose digitale</span>, <span class=\"kw-alerte\">gangrène</span>, <span class=\"kw-alerte\">infection locale</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sclérodermie systémique</span> ; <span class=\"kw-etio\">maladie de Buerger</span> (tabac/cannabis) ; processus <span class=\"kw-etio\">embolique</span></li><li><span class=\"kw-etio\">Marteau hypothénar</span> ; <span class=\"kw-etio\">maladie des vibrations</span> ; <span class=\"kw-etio\">syndrome myéloprolifératif</span> ; cause <span class=\"kw-etio\">paranéoplasique</span> ; <span class=\"kw-etio\">cryoglobulinémie</span> (<span class=\"kw-etio\">VHC</span>) ; <span class=\"kw-ci\">vasoconstricteurs</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span>, <span class=\"kw-bio\">cryoglobulinémie</span> ; <span class=\"kw-bio\">capillaroscopie</span> ; <span class=\"kw-imagerie\">écho-doppler artériel</span> ; mesure des pressions digitales ; recherche de cancer (<span class=\"kw-imagerie\">TDM-TAP</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Revascularisation</span> ; <span class=\"kw-ttt\">arrêt du tabac</span> ; <span class=\"kw-ttt\">traitement étiologique</span></li></ul><h4>Renvoi</h4><ul><li>Item 193 (<span class=\"kw-clinique\">vascularite</span> systémique) · Item 75 (tabac)</li></ul>"}]},"cards":[{"i":"24bfe40e2d03","n":239,"o":"239-1","u":"Définition","t":"Connaître la définition d’un phénomène de Raynaud, d’une acrocyanose, d’une érythermalgie, d’une ischémie digitale et d’une engelure","q":"Quelle est la définition d'un phénomène de Raynaud ?","a":"<p>Un phénomène de Raynaud est un acrosyndrome caractérisé par une <strong>vasoconstriction paroxystique</strong> des extrémités, en réponse au froid ou au stress, se manifestant par des crises en <strong>trois phases</strong> (blancheur, cyanose, rougeur). C'est un acrosyndrome vasomoteur.</p>"},{"i":"4511f0ace273","n":239,"o":"239-1","u":"Définition","t":"Connaître la définition d’un phénomène de Raynaud, d’une acrocyanose, d’une érythermalgie, d’une ischémie digitale et d’une engelure","q":"Quelle est la définition d'une ischémie digitale permanente ?","a":"<p>L'ischémie digitale permanente est un acrosyndrome traduisant des <strong>lésions artérielles ou microcirculatoires constituées</strong>. Elle se manifeste par une atteinte tissulaire permanente et est considérée comme une <strong>urgence</strong> en raison du risque de <strong>nécrose digitale</strong>. C'est un acrosyndrome trophique.</p>"},{"i":"ef1ae7c9a0c5","n":239,"o":"239-1","u":"Définition","t":"Connaître la définition d’un phénomène de Raynaud, d’une acrocyanose, d’une érythermalgie, d’une ischémie digitale et d’une engelure","q":"Quelle est la définition d'une engelure ?","a":"<p>Une engelure est un acrosyndrome caractérisé par une <strong>composante trophique (lésion tissulaire)</strong> survenant après une exposition au froid humide. Elle se présente sous une forme subaiguë, régressive en 2 à 3 semaines, et est un acrosyndrome trophique.</p>"},{"i":"f748167a9db6","n":239,"o":"239-1","u":"Définition","t":"Connaître la définition d’un phénomène de Raynaud, d’une acrocyanose, d’une érythermalgie, d’une ischémie digitale et d’une engelure","q":"Quelle est la définition d'une érythermalgie ?","a":"<p>L'érythermalgie est un acrosyndrome caractérisé par des crises paroxystiques de <strong>vasodilatation</strong> entraînant des douleurs urentes (brûlures intenses), une rougeur et une chaleur des extrémités. C'est un acrosyndrome vasomoteur dont l'étiologie doit être explorée, notamment à la recherche d'un syndrome myéloprolifératif.</p>"},{"i":"f838aaca8897","n":239,"o":"239-1","u":"Définition","t":"Connaître la définition d’un phénomène de Raynaud, d’une acrocyanose, d’une érythermalgie, d’une ischémie digitale et d’une engelure","q":"Quelle est la définition d'une acrocyanose ?","a":"<p>L'acrocyanose est un acrosyndrome caractérisé par une <strong>cyanose permanente et indolore</strong> des extrémités, particulièrement des mains et des pieds. Elle traduit une microangiopathie fonctionnelle bénigne et est un acrosyndrome vasomoteur.</p>"},{"i":"251b14c4e05a","n":239,"o":"239-2","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques des principaux acrosyndromes","q":"Comment se présentent les engelures cliniquement ?","a":"<p>Les engelures se manifestent par des <strong>maculo-papules violacées</strong> souvent <strong>œdémateuses</strong>, multiples et parfois confluentes en plaques. Elles siègent typiquement sur le <strong>dos des doigts et des orteils</strong>, les bords latéraux des pieds, la région achilléenne et l'hélix du nez. Les symptômes sont des <strong>brûlures douloureuses et un prurit</strong> au réchauffement. Elles surviennent dans un contexte de froid modéré humide et <strong>sans phase blanche syncopale</strong>. Elles régressent spontanément en 2-3 semaines, mais peuvent récidiver saisonnièrement.</p>"},{"i":"349d82b82ec5","n":239,"o":"239-2","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques des principaux acrosyndromes","q":"Quels sont les signes cliniques du phénomène de Raynaud ?","a":"<p>Le phénomène de Raynaud se caractérise par des crises déclenchées par le <strong>froid</strong>, les variations de température, l'humidité ou l'émotion. La topographie intéresse une ou plusieurs phalanges, parfois les orteils, le nez ou les oreilles. La crise évolue en <strong>3 phases</strong>, dont la survenue n'est pas constante pour toutes :</p><ul><li>Phase <strong>blanche syncopale</strong> (obligatoire et inaugurale) : doigts blancs, exsangues, à limites nettes, sensation de doigts morts, insensibles, parfois douloureux.</li><li>Phase <strong>cyanique</strong> (inconstante) : aspect bleuté, violacé, avec dysesthésies.</li><li>Phase <strong>érythémateuse</strong> (inconstante) : recoloration rouge avec réchauffement, dysesthésies souvent douloureuses.</li></ul><p>Entre les crises, l'examen est normal et aucun trouble trophique n'est présent dans la forme primitive.</p>"},{"i":"422cf5483180","n":239,"o":"239-2","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques des principaux acrosyndromes","q":"Comment distinguer l'acrocyanose cliniquement ?","a":"<p>L'acrocyanose est caractérisée par des <strong>extrémités froides et moites</strong>, de coloration <strong>érythrosique ou bleutée/violacée</strong>, parfois œdématiées. Ces signes sont :</p><ul><li><strong>Permanents</strong> (non paroxystiques).</li><li>Disparaissent à la <strong>vitropression</strong>.</li><li>Majorés par le froid et la déclivité.</li></ul><p>Elle est souvent associée à un <strong>livedo de stase déclive</strong> et une <strong>hyperhidrose</strong>. Un élément clé pour la distinguer du Raynaud est l'<strong>absence de phase blanche syncopale</strong> et son caractère indolore.</p>"},{"i":"a53ec906dade","n":239,"o":"239-2","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques des principaux acrosyndromes","q":"Quels sont les signes cliniques de l'ischémie digitale permanente ?","a":"<p>L'ischémie digitale permanente se caractérise par un doigt <strong>froid, douloureux, blanc ou cyanique</strong>. Les signes associés incluent des <strong>hémorragies sous-unguéales en flammèche</strong> et un <strong>temps de recoloration pulpaire allongé</strong>. Sur le plan trophique, on peut observer un <strong>infarctus péri-unguéal, une ulcération ou une nécrose digitale</strong>. Il s'agit d'une urgence en raison du risque d'infection locale et d'évolution vers la gangrène.</p>"},{"i":"e1d69d051465","n":239,"o":"239-2","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques des principaux acrosyndromes","q":"Quels sont les signes cliniques de l'érythermalgie ?","a":"<p>L'érythermalgie se manifeste par des crises paroxystiques (quelques minutes à quelques heures) où les extrémités (surtout les <strong>pieds</strong>) deviennent <strong>rouges, chaudes et intensément douloureuses</strong>. Les facteurs déclenchants incluent la <strong>chaleur</strong>, l'exercice et l'orthostatisme, tandis que le froid, le repos et l'élévation du membre apportent un soulagement. Il n'y a pas de pâleur ni de cyanose; la <strong>rougeur est isolée</strong> au territoire concerné.</p>"},{"i":"0ac2bf241488","n":239,"o":"239-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de distinguer Raynaud primitif et secondaire","q":"Quels examens complémentaires sont utiles pour distinguer un <strong>Raynaud primitif d'un secondaire</strong> et quels résultats attend-on dans chaque cas ?","a":"Deux examens sont clés :<ul><li>La <strong>capillaroscopie péri-unguéale</strong> : elle est <strong>normale</strong> en cas de Raynaud primitif et <strong>anormale</strong> (mégacapillaires, raréfaction capillaire) en cas de Raynaud secondaire.</li><li>La recherche d'<strong>anticorps anti-nucléaires (AAN)</strong> : ils sont <strong>négatifs</strong> dans le Raynaud primitif et peuvent être <strong>positifs</strong> (surtout en cas de connectivite associée) dans le Raynaud secondaire."},{"i":"27e300081aed","n":239,"o":"239-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de distinguer Raynaud primitif et secondaire","q":"Quels sont les principaux critères cliniques orientant vers un <strong>phénomène de Raynaud primitif</strong> ?","a":"Le phénomène de Raynaud primitif concerne typiquement la <strong>femme jeune</strong> (sex-ratio 4:1), avec un début <strong>avant 35-40 ans</strong>, souvent à l'adolescence. Il est <strong>bilatéral et symétrique</strong>, épargne les pouces, et la <strong>succession des trois phases</strong> (blancheur, cyanose, rougeur) est habituelle. Les <strong>troubles trophiques sont absents</strong> et l'examen physique est normal hors crise."},{"i":"8e96387e0f29","n":239,"o":"239-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de distinguer Raynaud primitif et secondaire","q":"Quels sont les '<strong>drapeaux rouges</strong>' cliniques qui doivent faire suspecter un <strong>phénomène de Raynaud secondaire</strong> ?","a":"Les drapeaux rouges incluent :<ul><li>Un <strong>début tardif après 40 ans</strong> ou chez un homme.</li><li>Une atteinte <strong>unilatérale ou asymétrique</strong>, avec <strong>atteinte des pouces</strong>.</li><li>La présence de <strong>troubles trophiques pulpaires</strong> (ulcérations, cicatrices rétractiles).</li><li>Des <strong>signes de connectivite</strong> (doigts boudinés, télangiectasies, sclérodactylie).</li><li>Des <strong>anomalies vasculaires</strong> (abolition d'un pouls, asymétrie tensionnelle, souffle).</li></ul>"},{"i":"a1618ce86355","n":239,"o":"239-3","u":"Diagnostic positif","t":"Connaître les éléments cliniques permettant de distinguer Raynaud primitif et secondaire","q":"Pourquoi la <strong>sclérodermie systémique</strong> est-elle un piège diagnostique majeur dans le phénomène de Raynaud ?","a":"La sclérodermie systémique représente un piège majeur car le <strong>phénomène de Raynaud est souvent inaugural</strong> et peut <strong>précéder de 10 ans</strong> les autres signes de la maladie. Tout Raynaud suspect de secondaire doit donc faire l'objet d'un <strong>suivi clinique prolongé</strong> avant de conclure à un caractère primitif."},{"i":"260b1f524cf1","n":239,"o":"239-6","u":"Contenu multimédia","t":"Photographies de phénomène de Raynaud (phase syncopale)","q":"Quelle est la phase inaugurale et indispensable du phénomène de Raynaud ?","a":"<p>La phase inaugurale et indispensable au diagnostic du phénomène de Raynaud est la phase <strong>syncopale</strong>, également appelée phase <strong>blanche</strong>.</p>"},{"i":"8ff21f2120a4","n":239,"o":"239-6","u":"Contenu multimédia","t":"Photographies de phénomène de Raynaud (phase syncopale)","q":"Quels sont les signes cliniques caractéristiques de la phase syncopale du phénomène de Raynaud ?","a":"<ul><li>Doigts <strong>blancs</strong>, <strong>exsangues</strong>, avec des limites <strong>très nettes</strong>.</li><li>Sensation de doigts <strong>morts</strong>, <strong>insensibles</strong>, et parfois <strong>douloureux</strong>.</li><li>Touche une ou plusieurs phalanges (parfois orteils, nez, oreilles).</li><li>La durée est de quelques minutes à quelques heures.</li></ul>"},{"i":"b1cf929f461d","n":239,"o":"239-6","u":"Contenu multimédia","t":"Photographies de phénomène de Raynaud (phase syncopale)","q":"Quel est l'élément clé pour confirmer le diagnostic de phénomène de Raynaud, en complément de l'interrogatoire ?","a":"<p>En complément de l'interrogatoire, le diagnostic de phénomène de Raynaud est conforté par des <strong>photographies de la crise prises par le patient</strong>.</p>"}]};